const localizedBodies: Record<Locale,string[]>={
en:sections.map(section=>section[1]),
de:["Die öffentliche Servicebeschreibung von LoloBuy nennt zwei überprüfbare Punkte: eine umfassende Qualitätsprüfung im Lager mit Rückmeldung und globalen Versand. Das ist nützlich, weil ein Artikel nach seinem Eintreffen sichtbar geprüft werden kann. Es ist aber keine Zusage, dass jedes Problem entdeckt wird, jedes Bild alle Fragen beantwortet oder jede Sendung denselben Zeitplan hat. Nutze die Aussage als Beginn einer Belegprüfung, nicht als Ersatz dafür.","Eine Produktseite beschreibt vor allem eine Absicht: gewählte Farbe, Größe, Variante und Verkäuferangaben. Lagerfeedback bezieht sich dagegen auf einen tatsächlich angekommenen Artikel. Wer vorab Variante, Preis, Größendaten und Hinweise speichert, kann später Erwartung und sichtbaren Artikel vergleichen. Ohne diesen Datensatz erinnert man sich leicht an Erwartungen statt an die tatsächlich gewählte Option. Die Prüfung beginnt deshalb mit der Bestellung und nicht mit dem ersten Eindruck eines Fotos.","Halte Produktname, Variante, Größe, Farbe, Menge und verfügbare Maße fest. Vergleiche beim Feedback zuerst beobachtbare Details: stimmt die sichtbare Farbe ungefähr, die Menge, das Etikett oder die Form? Gibt es deutliche Flecken, Schäden oder falsche Teile? Diese Reihenfolge macht die Prüfung wiederholbar. Sie verhindert zugleich, dass jede kleine Bildabweichung als Fehler gilt oder ein vertraut wirkendes Foto vorschnell als vollständige Bestätigung gelesen wird.","Bei einer Klärung helfen kurze Fragen mit Bezug zum Bild: Ist ein Fleck am linken Schuh sichtbar? Kann das Maßetikett gelesen werden? Ist dies die gewählte Farbvariante? Solche Fragen benennen Detail, Vergleich und Entscheidungspunkt. Sie sind verständlicher als ein allgemeines ‚Ist es gut?‘ und erzeugen eher eine brauchbare Antwort. Besonders bei ähnlichen Varianten sollte die gespeicherte Auswahl neben dem Feedback liegen; Erinnerung allein reicht nicht.","Lagerbilder können sichtbare Identität und erkennbaren Zustand zum Aufnahmezeitpunkt belegen. Sie können bei lesbaren Etiketten, offensichtlichen Farbabweichungen, sichtbarer Stückzahl, Verpackung oder deutlichen Markierungen helfen. Das ist bereits wertvoll, weil ein möglicher Unterschied vor dem Versand erkannt wird. Formuliere das Ergebnis jedoch passend zur Stärke des Belegs: ‚sichtbar mit der Auswahl vereinbar‘ ist belastbarer als ‚perfekt bestätigt‘.","Fotos beweisen nicht zuverlässig Passform, Materialzusammensetzung, Komfort, Haltbarkeit, Echtheit, Leistung oder jeden verdeckten Mangel. Blickwinkel, Licht, Kompression und gefaltete Kleidung verändern den Eindruck. Das ist eine allgemeine Grenze der Fernprüfung. Vergleiche bei Kleidung Zentimetermaße, wenn sie vorhanden sind, und lasse Toleranz zu. Bei Elektronik oder komplexen Waren darf Aussehen nicht als Leistungsnachweis gelten. Was nicht sichtbar ist, bleibt unbestätigt.","Die öffentliche Seite erwähnt globalen Versand. Das bedeutet jedoch nicht automatisch garantierte Route, Preis, Steuerbehandlung oder Lieferdatum. Diese Punkte hängen von Zielort, Paket, aktuellen Transportoptionen und geltenden Regeln ab. Sinnvoll ist daher: erst über den Artikel entscheiden, dann das Paket planen. Prüfe vor dem Absenden die aktuell angezeigten Bedingungen, Zielort-Eignung, Gewicht, Größe sowie für dich relevante Zoll- und Steuerangaben im Live-System.","Eine klare Checkliste lautet: ursprüngliche Produktseite und Auswahl sichern; Feedback mit der sichtbaren Bestellung vergleichen; nur beobachtbare Unterschiede notieren; präzise Fragen vor der Paketphase stellen; aktuelle Versandoptionen im Service prüfen; und die finale Entscheidung festhalten. Das ist bewusst sachlich. Es schafft eine nachvollziehbare Verbindung zwischen Auswahl, sichtbarem Artikel und Entscheidung. Es verringert Missverständnisse, beseitigt aber nicht die normale Unsicherheit bei Fernkauf und internationalem Versand.","Dieser Leitfaden behauptet nicht, dass LoloBuy eine bestimmte Zahl von Ländern bedient, feste Lieferzeiten oder Standardpreise bietet, jedes Produkt annimmt oder ein bestimmtes Verkäufer- oder Artikelresultat garantiert. Diese Aussagen konnten aus dem geprüften öffentlichen Material nicht belegt werden. Gute Recherche erklärt, was eine Quelle sagt, was ein Bild zeigen kann und wo der Beleg endet. Bleibt eine wichtige Frage offen, prüfe die aktuellen Serviceinformationen vor Zahlung oder Paketabgabe.","Der beste Nutzen von Lagerfeedback ist keine künstliche Sicherheit, sondern eine klarere nächste Entscheidung. Speichere Bestelldaten, prüfe Sichtbares, benenne die eine entscheidende Frage und kontrolliere Versandbedingungen erst nach der Artikelentscheidung. Die öffentliche Beschreibung stützt Lagerprüfungsfeedback und globalen Versand; die sorgfältige Kaufentscheidung bleibt beim Käufer. Ein kurzer Moment für Belege sorgt meist für mehr Klarheit im gesamten Vorgang."],
fr:["La description publique de LoloBuy cite deux éléments vérifiables : une inspection qualité complète en entrepôt avec retour, et une expédition mondiale. C’est utile car un article peut être examiné après son arrivée. Ce n’est pas la promesse que tout défaut sera repéré, que chaque image répondra à toutes les questions ou que chaque envoi suivra le même calendrier. Considérez cette information comme le début d’un contrôle par preuves, non comme son remplacement.","Une fiche produit décrit surtout une intention : couleur, taille, variante et informations du vendeur. Le retour d’entrepôt concerne au contraire un article physique arrivé sur place. Enregistrer la variante, le prix, les mesures et les notes avant commande permet une comparaison concrète ensuite. Sans trace, on confond facilement souvenir de l’attente et option réellement choisie. La vérification doit donc partir de la commande, pas d’une impression générale devant une photo.","Conservez le nom, la variante, la taille, la couleur, la quantité et les mesures disponibles. À la réception du retour, commencez par les éléments observables : couleur approximativement cohérente, quantité, étiquette, forme, marques ou pièces manquantes. Cette méthode rend l’examen répétable. Elle évite aussi de déclarer qu’une petite différence visuelle est forcément une erreur, ou qu’une image familière confirme automatiquement l’ensemble de la commande.","Pour demander une précision, posez une question courte liée à l’image : voit-on une marque sur la chaussure gauche ? Peut-on lire l’étiquette de mesure ? Est-ce bien la couleur choisie ? Une question précise indique le détail, la comparaison et la décision attendue. Elle est plus exploitable que ‘est-ce bon ?’. Avec des variantes proches, gardez toujours l’option enregistrée à côté du retour : la mémoire seule ne suffit pas.","Les images d’entrepôt peuvent constituer une preuve de l’identité visible et de l’état apparent au moment de la prise. Elles aident à vérifier une étiquette lisible, une différence de couleur évidente, le nombre d’articles, l’emballage ou une marque nette. C’est déjà utile avant expédition. Mais adaptez la conclusion à la preuve : ‘semble cohérent avec l’option sélectionnée’ est plus juste que ‘qualité parfaite confirmée’.","Une photo ne prouve pas de manière fiable l’ajustement, la composition, le confort, la durabilité, l’authenticité, le fonctionnement ou chaque défaut caché. Angle, lumière, compression et vêtement plié modifient la lecture. C’est une limite normale de l’examen à distance. Comparez les mesures en centimètres lorsqu’elles existent et gardez une marge de tolérance. Pour l’électronique ou un article complexe, l’apparence n’est jamais une preuve de performance. Ce qui n’est pas visible reste non confirmé.","La même page publique mentionne l’expédition mondiale. Cela ne garantit pas une route, un prix, un traitement fiscal ou une date de livraison. Ces éléments dépendent de la destination, du colis, des options disponibles et des règles du moment. Décidez donc d’abord de l’article, puis planifiez le colis. Avant soumission, vérifiez dans l’interface active les conditions actuelles, l’éligibilité de la destination, le poids, les dimensions et les informations douanières ou fiscales pertinentes.","Utilisez cette checklist : conservez la fiche et les options d’origine ; comparez le retour avec le dossier de commande ; ne notez que les écarts observables ; posez des questions précises avant la phase colis ; confirmez les choix d’expédition actuels dans le service ; gardez une trace de la décision finale. Cette méthode est volontairement simple. Elle relie clairement ce qui a été choisi, vu et décidé. Elle réduit des malentendus, sans supprimer l’incertitude normale de l’achat à distance ou international.","Ce guide ne prétend pas que LoloBuy dessert un nombre donné de pays, assure une vitesse fixe, applique un prix standard, accepte chaque produit ou garantit un résultat vendeur ou article. Nous n’avons pas pu vérifier ces affirmations dans le contenu public consulté. Une recherche utile explique ce qu’une source dit, ce qu’une image peut montrer et où s’arrête la preuve. Si une question importante reste ouverte, consultez les informations de service actuelles avant paiement ou soumission du colis.","Le meilleur usage du retour d’entrepôt n’est pas de créer une certitude artificielle, mais de rendre la prochaine décision plus claire. Gardez les détails de commande, observez ce qui est visible, isolez la question importante et vérifiez l’expédition seulement une fois l’article décidé. La description publique soutient l’existence d’un retour d’inspection et de l’expédition mondiale ; le choix prudent reste celui de l’acheteur. Quelques minutes consacrées aux preuves rendent souvent toute la commande plus claire."],
es:["La descripción pública de LoloBuy indica dos puntos verificables: inspección de calidad integral en almacén con comentarios y envío global. Es útil porque un artículo puede revisarse tras llegar al almacén. No promete detectar cada problema, que cada imagen responda todas las dudas ni que cada envío siga el mismo plazo. Toma esa afirmación como el inicio de una comprobación con evidencias, no como un sustituto de ella.","Una ficha de producto suele describir una intención: color, talla, variante y datos del vendedor. Los comentarios de almacén se refieren a un artículo físico ya recibido. Guardar variante, precio, medidas y notas antes de comprar permite una comparación real después. Sin ese registro, resulta fácil recordar la expectativa y no la opción elegida. Por eso la revisión debe comenzar por el pedido y no por una impresión general de la foto.","Guarda el nombre, variante, talla, color, cantidad y medidas disponibles. Al recibir comentarios, compara primero detalles observables: color aproximado, cantidad, etiqueta, forma, marcas claras o piezas incorrectas. El método hace la revisión repetible. También evita decidir que una diferencia visual pequeña es necesariamente un error, o que una imagen conocida confirma automáticamente todo. La evidencia útil se revisa paso a paso.","Cuando necesites aclarar algo, pregunta de forma corta y ligada a la evidencia: ¿hay una marca en el zapato izquierdo? ¿se puede leer la etiqueta de medida? ¿es esta la combinación de color elegida? Una pregunta concreta identifica el detalle, la comparación y la decisión. Es más útil que preguntar ‘¿está bien?’. Con variantes parecidas, mantén la selección guardada junto a los comentarios; la memoria no es suficiente.","Las imágenes de almacén pueden ayudar a comprobar identidad visible y estado aparente cuando fueron tomadas. Sirven para una etiqueta legible, una diferencia de color evidente, cantidad visible, estado del embalaje o una marca clara. Eso ya puede ayudar antes de enviar. La conclusión debe ser proporcional: ‘parece consistente con la opción’ es más sólido que ‘producto perfecto confirmado’. La precisión aumenta la confianza.","Las fotos no prueban de forma fiable ajuste, composición de material, comodidad, durabilidad, autenticidad, rendimiento ni todos los defectos ocultos. Ángulo, luz, compresión y ropa doblada cambian lo que se ve. Es un límite normal de revisar a distancia. Para ropa, compara medidas en centímetros si aparecen y admite tolerancia. Para electrónica o productos complejos, la apariencia no demuestra rendimiento. Lo que no sea observable sigue sin confirmar.","La página pública también menciona envío global, pero eso no equivale a una ruta, coste, impuesto o fecha de entrega garantizados. Depende de destino, características del paquete, opciones actuales y reglas vigentes. Decide primero sobre el artículo y planea el paquete después. Antes de enviar, revisa los términos actuales, elegibilidad del destino, peso, tamaño y la información de impuestos o aduanas aplicable en la interfaz activa.","Usa esta lista: conserva la ficha original y opciones; compara los comentarios con el pedido visible; anota solo diferencias observables; formula preguntas precisas antes de la fase de paquete; confirma opciones actuales de envío dentro del servicio; guarda la decisión final. Es un proceso deliberadamente sencillo. Crea una relación clara entre lo elegido, lo visto y lo decidido. Reduce malentendidos evitables, pero no elimina la incertidumbre normal de comprar a distancia o enviar internacionalmente.","Esta guía no afirma que LoloBuy atienda un número concreto de países, ofrezca velocidad fija, cobre un precio estándar, acepte cada producto o garantice un resultado de vendedor o artículo. No pudimos verificar tales afirmaciones en el material público revisado. Una investigación útil explica qué dice una fuente, qué puede mostrar una imagen y dónde termina la evidencia. Si queda una duda importante, revisa la información actual del servicio antes de pagar o enviar el paquete.","El mejor uso de los comentarios de almacén no es crear seguridad artificial, sino hacer más clara la siguiente decisión. Guarda los datos del pedido, revisa lo visible, identifica la única pregunta importante y confirma condiciones de envío cuando el artículo ya esté decidido. La descripción pública respalda comentarios de inspección y envío global; el cuidado final sigue siendo responsabilidad del comprador. Un minuto dedicado a evidencias suele aclarar todo el pedido."],
it:["La descrizione pubblica di LoloBuy presenta due elementi verificabili: controllo qualità completo in magazzino con feedback e spedizione globale. È utile perché l’articolo può essere esaminato dopo l’arrivo. Non promette che ogni problema sarà rilevato, che ogni foto risponderà a ogni domanda o che ogni spedizione avrà la stessa tempistica. Considera questa affermazione come l’inizio di una verifica basata su prove, non come un suo sostituto.","Una scheda prodotto esprime di solito un’intenzione: colore, taglia, variante e descrizione del venditore. Il feedback di magazzino riguarda invece un articolo fisico arrivato. Salvare variante, prezzo, misure e note prima dell’ordine permette un confronto concreto dopo. Senza una traccia, è facile ricordare l’aspettativa invece della scelta effettiva. La revisione deve quindi iniziare dal record dell’ordine, non dall’impressione generale di una foto.","Conserva nome, variante, taglia, colore, quantità e misure disponibili. Quando arriva il feedback, confronta prima elementi osservabili: colore, quantità, etichetta, forma, segni evidenti o componenti errati. Questo rende il controllo ripetibile. Evita anche di trattare ogni piccola differenza visiva come errore o un’immagine familiare come conferma completa. Le prove sono più utili quando sono confrontate in modo ordinato.","Se serve chiarimento, poni una domanda breve riferita all’immagine: c’è un segno sulla scarpa sinistra? si legge l’etichetta della misura? è questa la variante di colore selezionata? La domanda precisa definisce dettaglio, confronto e decisione. È più utile di ‘va bene?’. Con varianti simili, mantieni la scelta salvata vicino al feedback; la memoria non basta per una decisione affidabile.","Le immagini del magazzino possono mostrare identità visibile e condizione apparente nel momento dello scatto. Aiutano con etichette leggibili, differenze di colore evidenti, quantità, imballaggio o segni chiari. È già utile prima della spedizione. Però la conclusione deve rispettare la prova: ‘sembra coerente con la scelta’ è più corretto di ‘qualità perfetta confermata’. Una formulazione proporzionata rende la ricerca più credibile.","Le foto non dimostrano con affidabilità vestibilità, composizione, comfort, durata, autenticità, prestazioni o ogni difetto nascosto. Angolo, luce, compressione e un capo piegato cambiano la percezione. È un limite normale della verifica a distanza. Per l’abbigliamento confronta misure in centimetri quando disponibili e lascia una tolleranza. Per elettronica o beni complessi l’aspetto non prova le prestazioni. Ciò che non è osservabile rimane non confermato.","La pagina pubblica cita anche la spedizione globale, ma non equivale a percorso, costo, tasse o data garantiti. Dipende dalla destinazione, dal pacco, dalle opzioni correnti e dalle regole del momento. Decidi prima sull’articolo e pianifica il pacco dopo. Prima dell’invio, verifica nell’interfaccia attiva condizioni, idoneità della destinazione, peso, dimensioni e informazioni doganali o fiscali pertinenti.","Usa questa checklist: conserva scheda e opzioni originali; confronta feedback e record visibile dell’ordine; annota solo differenze osservabili; poni domande precise prima della fase pacco; conferma le opzioni di spedizione attuali nel servizio; conserva la decisione finale. È una procedura volutamente semplice. Collega chiaramente ciò che hai scelto, visto e deciso. Riduce equivoci evitabili, ma non elimina la normale incertezza dell’acquisto remoto o internazionale.","Questa guida non sostiene che LoloBuy serva un numero specifico di paesi, offra velocità fissa, applichi un prezzo standard, accetti ogni prodotto o garantisca un esito per venditore o articolo. Non abbiamo potuto verificare tali affermazioni nel materiale pubblico esaminato. Una buona ricerca spiega cosa dice la fonte, cosa può mostrare un’immagine e dove termina la prova. Se resta una domanda importante, controlla le informazioni correnti prima del pagamento o dell’invio.","Il miglior uso del feedback di magazzino non è creare certezza artificiale, ma rendere più esplicita la decisione successiva. Salva l’ordine, controlla il visibile, individua l’unica domanda importante e verifica la spedizione solo quando l’articolo è deciso. La descrizione pubblica sostiene feedback di controllo e spedizione globale; la scelta prudente resta dell’acquirente. Un momento dedicato alle prove rende spesso più chiaro l’intero ordine."],
pt:["A descrição pública da LoloBuy apresenta dois pontos verificáveis: inspeção de qualidade abrangente no armazém com feedback e envio global. Isto é útil porque um artigo pode ser revisto depois de chegar ao armazém. Não promete que todo o problema será encontrado, que cada imagem responde a tudo ou que todas as expedições seguem o mesmo prazo. Use esta informação como início de uma verificação por evidências, não como substituto dela.","Uma página de produto descreve normalmente uma intenção: cor, tamanho, variante e informação do vendedor. O feedback de armazém refere-se, pelo contrário, a um artigo físico que chegou. Guardar variante, preço, medidas e notas antes de encomendar permite comparar depois com algo concreto. Sem este registo, é fácil lembrar a expectativa e não a opção escolhida. A revisão deve começar pelo pedido, não por uma impressão geral da fotografia.","Guarde nome, variante, tamanho, cor, quantidade e medidas disponíveis. Quando houver feedback, compare primeiro detalhes observáveis: cor aproximada, quantidade, etiqueta, forma, marcas evidentes ou peças erradas. Este método torna a revisão repetível. Evita também concluir que uma diferença pequena é necessariamente erro, ou que uma imagem familiar confirma tudo. A evidência é mais útil quando é avaliada de forma ordenada.","Quando precisar de esclarecimento, faça uma pergunta curta ligada à imagem: há uma marca no sapato esquerdo? a etiqueta de medida pode ser lida? esta é a cor selecionada? Uma pergunta específica identifica detalhe, comparação e decisão. É mais útil do que ‘está bom?’. Em variantes semelhantes, mantenha a seleção guardada junto do feedback; só a memória não basta.","Imagens de armazém podem ajudar a confirmar identidade visível e condição aparente no momento da fotografia. Podem mostrar uma etiqueta legível, diferença clara de cor, quantidade visível, estado da embalagem ou uma marca evidente. Isto já ajuda antes do envio. Ajuste a conclusão à prova: ‘parece coerente com a opção selecionada’ é mais sólido do que ‘perfeito confirmado’. Precisão cria confiança.","Fotografias não provam de forma fiável ajuste, composição, conforto, durabilidade, autenticidade, desempenho ou todos os defeitos ocultos. Ângulo, luz, compressão e roupa dobrada alteram o que se vê. É um limite normal da revisão à distância. Para roupa, compare medidas em centímetros quando existirem e aceite tolerância. Para eletrónica ou artigos complexos, aparência não prova desempenho. O que não é visível permanece não confirmado.","A mesma página pública refere envio global, mas isso não é rota, custo, imposto ou data garantidos. Esses pontos dependem do destino, do pacote, das opções atuais e das regras vigentes. Decida primeiro sobre o artigo e planeie a encomenda depois. Antes de submeter, confirme na interface ativa termos atuais, elegibilidade do destino, peso, dimensões e informação aduaneira ou fiscal relevante.","Use esta checklist: guarde a página e opções originais; compare o feedback com o registo visível; anote apenas diferenças observáveis; faça perguntas precisas antes da fase de envio; confirme opções atuais no serviço; guarde a decisão final. É deliberadamente simples. Cria uma ligação clara entre o que escolheu, viu e decidiu. Reduz mal-entendidos evitáveis, mas não elimina a incerteza normal de compras remotas ou envio internacional.","Este guia não afirma que a LoloBuy serve determinado número de países, oferece velocidade fixa, cobra preço padrão, aceita todo produto ou garante resultado de vendedor ou artigo. Não foi possível verificar estas afirmações no material público revisto. Uma pesquisa útil explica o que uma fonte diz, o que uma imagem pode mostrar e onde termina a evidência. Se uma questão importante continuar em aberto, confirme o serviço atual antes de pagar ou enviar.","O melhor uso do feedback de armazém não é criar segurança artificial, mas tornar mais clara a próxima decisão. Guarde detalhes da encomenda, observe o visível, identifique a pergunta decisiva e confirme o envio apenas quando o artigo estiver decidido. A descrição pública sustenta feedback de inspeção e envio global; a decisão prudente continua a ser do comprador. Um minuto dedicado à evidência torna normalmente todo o pedido mais claro."],
nl:["De openbare LoloBuy-serviceomschrijving noemt twee verifieerbare punten: uitgebreide kwaliteitsinspectie in het magazijn met feedback en wereldwijde verzending. Dat is nuttig omdat een artikel na aankomst zichtbaar kan worden beoordeeld. Het is geen belofte dat elk probleem gevonden wordt, dat elke foto iedere vraag beantwoordt of dat iedere zending dezelfde planning heeft. Zie de uitspraak als begin van een bewijscontrole, niet als vervanging daarvan.","Een productpagina beschrijft meestal een bedoeling: gekozen kleur, maat, variant en verkopersinformatie. Magazijnfeedback gaat daarentegen over een fysiek artikel dat is aangekomen. Wie variant, prijs, maten en notities vooraf bewaart, kan later concreet vergelijken. Zonder dit record herinner je gemakkelijk de verwachting in plaats van de gekozen optie. De beoordeling begint daarom bij de bestelling en niet bij een algemene indruk van een foto.","Bewaar productnaam, variant, maat, kleur, aantal en beschikbare maten. Vergelijk bij feedback eerst waarneembare details: past de zichtbare kleur ongeveer, klopt het aantal, label of vorm, zijn er duidelijke vlekken, schade of verkeerde onderdelen? Deze volgorde maakt beoordeling herhaalbaar. Ze voorkomt ook dat een klein verschil meteen als fout geldt of een vertrouwde foto te snel als volledige bevestiging wordt gelezen.","Stel bij een verduidelijking een korte vraag die aan het beeld is gekoppeld: is er een markering op de linker schoen? is het maatlabel leesbaar? is dit de gekozen kleurvariant? Een scherpe vraag noemt detail, vergelijking en beslismoment. Dat werkt beter dan ‘is het goed?’. Bij vergelijkbare varianten moet de bewaarde keuze naast de feedback liggen; alleen geheugen is onvoldoende.","Magazijnfoto’s kunnen zichtbaar identiteit en ogenschijnlijke conditie tonen op het moment van opname. Ze kunnen helpen bij leesbaar label, duidelijk kleurverschil, zichtbaar aantal, verpakking of opvallende markering. Dat is al waardevol vóór verzending. Pas de conclusie wel aan het bewijs aan: ‘lijkt overeen te komen met de gekozen optie’ is sterker dan ‘perfecte kwaliteit bevestigd’. Nauwkeurige formulering bouwt vertrouwen op.","Foto’s bewijzen niet betrouwbaar pasvorm, materiaalsamenstelling, comfort, duurzaamheid, authenticiteit, prestaties of ieder verborgen gebrek. Hoek, licht, compressie en een opgevouwen kledingstuk beïnvloeden wat je ziet. Dit is een normale beperking van beoordeling op afstand. Vergelijk bij kleding centimeters als ze beschikbaar zijn en houd rekening met tolerantie. Bij elektronica of complexe goederen is uiterlijk geen prestatiebewijs. Wat niet zichtbaar is, blijft onbevestigd.","Dezelfde openbare pagina noemt wereldwijde verzending, maar dat is niet hetzelfde als een gegarandeerde route, prijs, belastingbehandeling of leverdatum. Dit hangt af van bestemming, pakket, huidige vervoersopties en regels op dat moment. Beslis eerst over het artikel en plan daarna het pakket. Controleer vóór indienen actuele voorwaarden, geschiktheid van de bestemming, gewicht, formaat en relevante douane- of belastinginformatie in de live-interface.","Gebruik deze checklist: bewaar oorspronkelijke productpagina en opties; vergelijk feedback met het zichtbare orderrecord; noteer alleen waarneembare verschillen; stel precieze vragen vóór de pakketfase; bevestig actuele verzendkeuzes in de service; bewaar de eindbeslissing. Dit is bewust eenvoudig. Het verbindt wat je koos, zag en besloot. Het vermindert vermijdbare misverstanden, maar neemt de normale onzekerheid van kopen op afstand of internationale verzending niet weg.","Deze gids beweert niet dat LoloBuy een bepaald aantal landen bedient, vaste snelheid biedt, een standaardprijs rekent, ieder product accepteert of een specifieke verkoper- of artikeluitkomst garandeert. We konden dergelijke claims niet verifiëren in het openbare materiaal dat we bekeken. Goed onderzoek legt uit wat een bron zegt, wat een beeld kan tonen en waar het bewijs eindigt. Blijft een belangrijke vraag open, controleer dan actuele service-informatie vóór betaling of pakketindiening.","Het beste gebruik van magazijnfeedback is niet kunstmatige zekerheid creëren, maar de volgende keuze duidelijker maken. Bewaar orderdetails, inspecteer wat zichtbaar is, benoem de ene belangrijke vraag en controleer verzending pas wanneer het artikel is besloten. De openbare omschrijving ondersteunt inspectiefeedback en wereldwijde verzending; de zorgvuldige beslissing blijft bij de koper. Een minuut voor bewijs maakt doorgaans de hele bestelling helderder."],
pl:["Publiczny opis usługi LoloBuy wskazuje dwa weryfikowalne elementy: kompleksową kontrolę jakości w magazynie z informacją zwrotną oraz globalną wysyłkę. To użyteczne, bo artykuł można ocenić po dotarciu do magazynu. Nie jest to obietnica wykrycia każdego problemu, odpowiedzi na każde pytanie przez każde zdjęcie ani identycznego harmonogramu każdej przesyłki. Traktuj tę deklarację jako początek kontroli dowodów, a nie jej zastępstwo.","Strona produktu opisuje zwykle zamiar: wybrany kolor, rozmiar, wariant i opis sprzedawcy. Feedback z magazynu dotyczy natomiast fizycznego artykułu, który już dotarł. Zapisanie wariantu, ceny, wymiarów i notatek przed zamówieniem daje później konkretny punkt porównania. Bez zapisu łatwo pamiętać oczekiwanie, a nie faktycznie wybraną opcję. Kontrola powinna więc zaczynać się od zamówienia, a nie od ogólnego wrażenia ze zdjęcia.","Zachowaj nazwę, wariant, rozmiar, kolor, ilość i dostępne wymiary. Po otrzymaniu informacji porównuj najpierw szczegóły obserwowalne: przybliżony kolor, ilość, etykietę, kształt, wyraźne ślady, uszkodzenia lub błędne części. Ta kolejność czyni sprawdzenie powtarzalnym. Chroni też przed uznaniem każdej drobnej różnicy obrazu za błąd albo znajomego zdjęcia za pełne potwierdzenie.","Gdy potrzebujesz wyjaśnienia, zadawaj krótkie pytanie związane z dowodem: czy na lewym bucie jest ślad? czy można odczytać etykietę z wymiarem? czy to wybrana kolorystyka? Konkretne pytanie określa detal, porównanie i decyzję. Jest użyteczniejsze niż pytanie ‘czy jest dobre?’. Przy podobnych wariantach zapisany wybór powinien leżeć obok feedbacku; sama pamięć nie wystarcza.","Zdjęcia z magazynu mogą potwierdzić widoczną tożsamość i pozorny stan w chwili wykonania. Pomagają przy czytelnej etykiecie, oczywistej różnicy koloru, widocznej liczbie, stanie opakowania lub wyraźnym śladzie. To już jest wartościowe przed wysyłką. Wniosek powinien odpowiadać dowodowi: ‘wygląda zgodnie z wybraną opcją’ jest mocniejsze niż ‘idealna jakość potwierdzona’. Precyzja zwiększa wiarygodność.","Zdjęcia nie dowodzą wiarygodnie dopasowania, składu, komfortu, trwałości, autentyczności, działania ani każdego ukrytego defektu. Kąt, światło, kompresja i złożona odzież zmieniają odbiór. To zwykłe ograniczenie zdalnej oceny. Przy odzieży porównuj wymiary w centymetrach, jeśli są dostępne, i uwzględniaj tolerancję. Dla elektroniki wygląd nie dowodzi działania. To, czego nie można zobaczyć, pozostaje niepotwierdzone.","Ta sama strona publiczna wspomina globalną wysyłkę, lecz nie oznacza to gwarantowanej trasy, ceny, podatku ani daty doręczenia. Zależy to od kraju, paczki, bieżących opcji przewoźnika i aktualnych zasad. Najpierw zdecyduj o artykule, a potem planuj paczkę. Przed wysłaniem sprawdź w aktywnym interfejsie aktualne warunki, dostępność dla kraju, wagę, wymiary oraz istotne informacje celne i podatkowe.","Użyj tej listy: zachowaj oryginalną stronę i opcje; porównaj feedback z widocznym zamówieniem; zapisuj tylko obserwowalne różnice; zadawaj precyzyjne pytania przed etapem paczki; potwierdź aktualne opcje wysyłki w usłudze; zachowaj końcową decyzję. Proces jest celowo prosty. Łączy to, co wybrano, zobaczono i postanowiono. Ogranicza możliwe nieporozumienia, ale nie usuwa zwykłej niepewności zakupów zdalnych i międzynarodowej wysyłki.","Ten przewodnik nie twierdzi, że LoloBuy obsługuje określoną liczbę krajów, zapewnia stałe tempo, stosuje standardową cenę, akceptuje każdy produkt lub gwarantuje wynik dla sprzedawcy czy artykułu. Nie mogliśmy potwierdzić takich stwierdzeń w sprawdzonym materiale publicznym. Dobra analiza wyjaśnia, co mówi źródło, co może pokazać obraz i gdzie kończy się dowód. Jeśli ważne pytanie pozostaje otwarte, sprawdź aktualne informacje przed płatnością lub wysłaniem paczki.","Najlepszym zastosowaniem feedbacku z magazynu nie jest tworzenie sztucznej pewności, lecz wyraźniejsze podjęcie kolejnej decyzji. Zapisz dane zamówienia, obejrzyj to, co widoczne, wskaż jedno ważne pytanie i sprawdź wysyłkę dopiero po decyzji o artykule. Publiczny opis potwierdza feedback z kontroli i globalną wysyłkę; ostrożna decyzja nadal należy do kupującego. Minuta poświęcona dowodom często rozjaśnia całe zamówienie."],
sv:["LoloBuys offentliga servicebeskrivning nämner två verifierbara punkter: omfattande kvalitetsinspektion i lagret med återkoppling och global frakt. Det är användbart eftersom en vara kan granskas efter ankomst. Det är inte ett löfte om att varje problem upptäcks, att varje bild besvarar alla frågor eller att varje försändelse följer samma tidplan. Se uttalandet som början på en beviskontroll, inte som en ersättning för den.","En produktsida beskriver oftast en avsikt: vald färg, storlek, variant och säljarinformation. Lageråterkoppling gäller däremot en fysisk vara som har anlänt. Den som sparar variant, pris, mått och anteckningar före beställning kan jämföra med något konkret senare. Utan denna uppgift är det lätt att minnas förväntningen i stället för det verkliga valet. Granskningen bör därför börja med ordern och inte med ett allmänt intryck av ett foto.","Spara produktnamn, variant, storlek, färg, antal och tillgängliga mått. När återkoppling finns, jämför först observerbara detaljer: ungefärlig färg, antal, etikett, form, tydliga märken, skador eller fel delar. Den ordningen gör granskningen upprepbar. Den hindrar också att varje liten bildskillnad behandlas som fel eller att en bekant bild blir en för snabb total bekräftelse.","När något behöver klargöras, ställ en kort fråga som hör till bilden: finns ett märke på vänster sko? kan måttetiketten läsas? är detta den valda färgvarianten? En precis fråga visar detalj, jämförelse och beslutspunkt. Den fungerar bättre än ‘är den bra?’. Vid lika varianter måste det sparade valet finnas bredvid återkopplingen; minnet ensamt räcker inte.","Lagerbilder kan ge stöd för synlig identitet och synligt skick när bilden togs. De kan hjälpa med läsbar etikett, uppenbar färgskillnad, synligt antal, emballage eller tydligt märke. Det är redan värdefullt före frakt. Anpassa dock slutsatsen till beviset: ‘ser förenlig ut med valt alternativ’ är starkare än ‘perfekt kvalitet bekräftad’. Exakt språk skapar förtroende.","Fotografier bevisar inte tillförlitligt passform, materialsammansättning, komfort, hållbarhet, äkthet, funktion eller varje dold defekt. Vinkel, ljus, komprimering och ett vikt plagg påverkar det du ser. Det är en normal begränsning vid granskning på distans. Jämför centimeter-mått för kläder när de finns och lämna tolerans. För elektronik eller komplexa varor är utseende inget prestationsbevis. Det som inte syns är fortfarande obekräftat.","Samma offentliga sida nämner global frakt, men det betyder inte garanterad rutt, kostnad, skatt eller leveransdatum. Det beror på destination, paket, aktuella transportval och regler vid tidpunkten. Bestäm först om varan och planera paketet därefter. Innan inskick, kontrollera aktuella villkor, destinationsbehörighet, vikt, storlek och relevant tull- eller skatteinformation i det aktiva gränssnittet.","Använd denna checklista: spara ursprunglig sida och val; jämför återkopplingen med synlig orderuppgift; anteckna bara observerbara skillnader; ställ precisa frågor före paketsteget; bekräfta aktuella fraktval i tjänsten; spara slutligt beslut. Processen är medvetet enkel. Den kopplar ihop vad du valde, såg och beslutade. Den minskar undvikbara missförstånd men tar inte bort den normala osäkerheten vid distansköp och internationell frakt.","Denna guide påstår inte att LoloBuy betjänar ett visst antal länder, ger fast leveranshastighet, tar ett standardpris, accepterar varje produkt eller garanterar ett visst säljar- eller varuresultat. Vi kunde inte verifiera sådana påståenden i det offentliga material vi granskade. Bra research förklarar vad en källa säger, vad en bild kan visa och var beviset slutar. Om en viktig fråga är öppen, kontrollera aktuell serviceinformation före betalning eller paketinsändning.","Den bästa användningen av lageråterkoppling är inte att skapa konstgjord säkerhet utan att göra nästa beslut tydligare. Spara orderdetaljer, granska det synliga, identifiera den viktiga frågan och kontrollera frakten först när varan är beslutad. Den offentliga beskrivningen stödjer inspektionsåterkoppling och global frakt; det försiktiga beslutet ligger fortfarande hos köparen. En minut för bevis gör vanligtvis hela ordern klarare."]
};

export default function SeoArticles(){
  const locale=useSiteLocale(); const t=labels[locale];
  return <main className="min-h-screen bg-[#e8ebf4] text-[#10213b]"><SiteHeader/><section className="mx-auto max-w-4xl px-5 pb-16 pt-12 sm:px-8"><p className="text-xs font-extrabold tracking-[.16em] text-[#ff6947]">{t.eyebrow}</p><h1 className="mt-3 text-4xl font-black leading-[.98] tracking-[-.06em] sm:text-6xl">{t.title}</h1><p className="mt-6 max-w-3xl text-lg leading-relaxed text-[#40506d]">{t.intro}</p><article className="mt-10 rounded-[2rem] bg-white p-6 shadow-sm sm:p-10"><p className="text-sm font-bold tracking-[.12em] text-[#1647cf]">{t.guide}</p><div className="mt-8 space-y-10">{sections.map(([heading],index)=><section key={heading}><h2 className="text-2xl font-black tracking-[-.04em]">{translatedHeadings[locale][index]}</h2><p className="mt-3 text-base leading-8 text-[#40506d]">{localizedBodies[locale][index]}</p></section>)}</div><aside className="mt-10 rounded-2xl border border-[#cbd3e6] bg-[#edf1fb] p-5 text-sm leading-7 text-[#40506d]">{t.source}</aside></article></section></main>;
}
